import assert from'node:assert/strict';import path from'node:path';import{writeFile}from'node:fs/promises';import{chromium}from'playwright';import{serveStatic}from'../../engine/static.mjs';import{load}from'cheerio';import{calendarClock,calendarToday}from'../../scripts/calendar-clock.mjs';
const artifact=path.resolve('artifacts/platform/events-heldout'),origin='http://127.0.0.1:9440';let browser,server;const cases=[];
try{
 const metadata=await(await fetch(origin+'/wp-json/')).json(),clock=calendarClock(metadata),sourceHTML=await(await fetch(origin+'/events/today/')).text(),$=load(sourceHTML),data=JSON.parse($('[data-js="tribe-events-view-data"]').first().text()),today=data.today.slice(0,10);assert.deepEqual(clock,{timeZone:metadata.timezone_string});assert.equal(calendarToday(clock),today);
 server=await serveStatic(path.join(artifact,'project/output'));browser=await chromium.launch({channel:'chrome'});
 for(const width of [1440,390])for(const timezoneId of ['Pacific/Pago_Pago','Pacific/Kiritimati']){const pair=[];for(const [kind,url]of [['source',origin+'/events/today/'],['export',server.url+'/events/2028-03-11/?calendar-date='+today]]){const page=await browser.newPage({timezoneId,viewport:{width,height:900}});assert.equal((await page.goto(url,{waitUntil:'networkidle'})).status(),200);if(kind==='export'){assert.deepEqual(JSON.parse(await page.locator('[data-migration-calendar]').first().getAttribute('data-migration-calendar-clock')),clock);await page.waitForFunction(day=>document.querySelector('.tribe-events-c-top-bar__datepicker-time')?.getAttribute('datetime')===day,today);}await page.locator('.tribe-events-c-top-bar__datepicker-button').click();const current=page.locator('.datepicker:visible .day.current');await current.waitFor();const date=await current.getAttribute('data-date');assert.equal(date,String(Date.parse(today+'T00:00:00Z')));pair.push({kind,currentDay:today,visitorDay:await page.evaluate(()=>[new Date().getFullYear(),String(new Date().getMonth()+1).padStart(2,'0'),String(new Date().getDate()).padStart(2,'0')].join('-'))});await page.close();}cases.push({width,timezoneId,pair});}
 const result={scope:'Installed source and native export picker current-day parity across visitor timezones; live site clock, no frozen capture date',clock,cases};await writeFile(path.join(artifact,'clock-generated-check.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));
}finally{await browser?.close();await server?.close();}
